// Regenerates src/content/case-studies/index.ts from the files in that folder,
// so adding a case study is just dropping a new `<slug>.ts` file in.
import { readdirSync, writeFileSync } from "node:fs";
import { join } from "node:path";

const dir = join(import.meta.dirname, "../src/content/case-studies");
const files = readdirSync(dir)
  .filter((f) => f.endsWith(".ts") && f !== "index.ts")
  .sort();

const ident = (f) => "cs_" + f.replace(/\.ts$/, "").replace(/[^a-zA-Z0-9]/g, "_");
const lines = [
  "// Generated by scripts/gen-case-study-index.mjs — do not edit by hand.",
  'import type { CaseStudy } from "../types";',
  ...files.map((f) => `import ${ident(f)} from "./${f.replace(/\.ts$/, "")}";`),
  "",
  "export const CASE_STUDY_MODULES: Record<string, CaseStudy> = Object.fromEntries(",
  `  [${files.map(ident).join(", ")}].map((study) => [study.slug, study]),`,
  ");",
  "",
];
writeFileSync(join(dir, "index.ts"), lines.join("\n"));
console.log(`case-studies/index.ts: ${files.length} entries`);
